/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_user` int NOT NULL,
  `message` varchar(300) COLLATE utf8mb4_general_ci NOT NULL,
  `date` date NOT NULL,
  `star` enum('1','2','3','4','5') COLLATE utf8mb4_general_ci NOT NULL,
  `delete_message` bit(1) NOT NULL,
  `sending_message` enum('DRAFT','PUBLISHED','','') COLLATE utf8mb4_general_ci NOT NULL,
  `experience` enum('NEOPHYTE','BEGINNER','INTERMEDIATE','ESPERTO','PILOT') COLLATE utf8mb4_general_ci NOT NULL,
  `id_street` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `id_user` (`id_user`),
  KEY `id_street` (`id_street`),
  CONSTRAINT `review_ibfk_1` FOREIGN KEY (`id_user`) REFERENCES `account` (`id`),
  CONSTRAINT `review_ibfk_2` FOREIGN KEY (`id_street`) REFERENCES `street` (`id`)
